--
-- Triggers `bookshelf`
--
DELIMITER $$
CREATE TRIGGER `trg_bookshelf_ai` AFTER INSERT ON `bookshelf` FOR EACH ROW BEGIN
  DECLARE author_id INT;
  SELECT users_id INTO author_id FROM novels WHERE novels_id = NEW.novels_id;
  IF author_id IS NOT NULL THEN
    INSERT INTO notifications (
      users_id, actor_user_id, type, novel_id, reference_id, message, is_read, created_at
    ) VALUES (
      author_id, NEW.users_id, 'bookshelf_add', NEW.novels_id, NEW.bookshelf_id,
      'นิยายของคุณถูกเพิ่มเข้าชั้นหนังสือของผู้อ่าน', 0, NOW()
    );
  END IF;
END
$$
DELIMITER ;

