INSERT INTO `chapters` (`chapters_id`, `novels_id`, `title`, `content_html`, `chapter_no`, `created_at`, `like_count`, `status`, `updated_at`) VALUES
(1, 1, 'The one', '\r\n\r\n\r\n\r\n\r\n\r\n          ที่พักอาศัยลูกชายคนเล็กของจรัสณรงค์กุลดูเรียบง่ายและเหมาะสมกับนิสัยเจ้าตัว การจัดวางเฟอร์นิเจอร์หรือรูปภาพบนผนังก็ทำได้อย่างสวยงาม แต่การเดินชมห้องพักของจรัลไม่ใช่จุดประสงค์หลักของค่ำคืนนี้\r\n\r\n         แต่เป็นเพราะทิทัตน์และจรัลมีเรื่องมากมายที่ต้องการจะพูดคุยกัน\r\n\r\n          \"ผ้าขนหนูแขวนไว้ให้ในห้องน้ำนะ แปรงสีฟันถ้าไม่ได้เอามา ทัตน์เปิดดูลิ้นชักตรงอ่างล้างหน้าได้เลย\" เป็นเสียงเจ้าของห้องที่เดินหายไปในห้องนอนและทิ้งแมวต่างถิ่นให้สำรวจห้องอยู่คนเดียว\r\n\r\n        \"ขอบคุณครับ\" แมวแปลกที่เอ่ยขอบคุณและไม่ลืมเอ่ยชมการจัดห้องของอีกฝ่าย\r\n\r\n        \"แต่งห้องสวยดีนะ\"\r\n\r\nจรัลยิ้มรับคำชมทั้งยังเอ่ยปากให้ทิทัตน์เข้าไปอาบน้ำเสียที ส่วนตัวเจ้าของห้องเพราะยกห้องน้ำในห้องนอนให้ทิทัตน์ไปแล้วจึงย้ายตัวเองไปอาบน้ำในห้องน้ำอีกห้องแทน\r\n\r\nคอนโดมิเนียมของจรัลแม้จะอาศัยอยู่คนเดียวเสียส่วนใหญ่แต่ก็ซื้อที่เป็นสองห้องนอนไว้เผื่อว่าวันไหนครอบครัวจะมาเยี่ยมเยียนและมาค้างกับเขาบ้าง เมื่อก่อนจิรัชคือขาประจำของห้องรับรองนั้น แต่หลังจากมีแฟนพี่ชายตัวดีของเขาก็ไม่ค่อยจะมาให้เห็นหน้าบ่อยเท่าเดิม\r\n\r\n\r\n\r\n\"มานั่งนี่มา\"\r\n\r\nทิทัตน์อาบน้ำเสร็จก่อนและนั่งทำงานเล็ก ๆ น้อย ๆ รออยู่บนโซฟากลางห้อง สวมแว่นตาที่จรัลไม่ค่อยได้เห็นอีกคนใส่บ่อยนัก ก่อนจะพับปิดจอแล็ปท็อปเมื่อเจ้าของห้องทิ้งตัวลงใกล้ ๆ ขยับตัวให้คนมาใหม่ซ้อนหลังแล้วจึงเอนหัวซบลงบนอกของจรัล\r\n\r\nเจ้าของห้องยิ้มเอ็นดู ไม่ลืมที่จะโอบกอดอย่างคุ้นเคย\r\n\r\nพอรู้ว่าเขาจำได้ทิทัตน์ก็เผยนิสัยเดิม ๆ และกล้าทิ้งตัวแบบที่เคยทำเสมอ\r\n\r\n\"เจ\"\r\n\r\n\"ว่ายังไง\"\r\n\r\n\"ที่บอกว่าที่บ้านรู้น่ะ เขารู้ได้ไง\"\r\n\r\n\"ก็อย่างที่เจบอก เขาเลี้ยงของเขามา เจมาโผล่นี่ก็อายุสิบแปด โคตรรู้สึกผิดเลยที่ได้ชีวิตใครมาไม่รู้ ทัตน์ก็น่าจะเป็นเหมือนกันไหม ที่ความทรงจำเขาทุกอย่างก็ยังอยู่ในนี้ พอเริ่มทำตัวแปลก ๆ ไปเขาก็สังเกตได้ แต่ไม่ได้เข้ามาถามอะไรหรอก จนเจหนีออกไปนั่นแหละเขาถึงขอให้เจเปิดใจเล่าให้ฟัง\"\r\n\r\n\"ทุกคนไม่ช็อกไปเลยเหรอ\"\r\n\r\n\"ถ้าพูดเร็วกว่านั้นก็คงมีช็อกแหละ แต่เจได้พูดออกมาตอนเขาเริ่มทำใจกันบ้างแล้วว่าเจไม่ใช่ลูกเขาคนเก่า ว่ายังไงดี เขาก็มีที่พึ่งทางจิตวิญญาณของตัวเองอยู่บ้าง ทางนั้นก็พูดเปรย ๆ ว่าเจไม่ใช่คนเดิม เขาทำใจกันตั้งนานแล้ว เจเล่าทุกเรื่องนั่นแหละให้เขาฟัง\"\r\n\r\n\"ดีจังที่เจอคนดี ๆ เต็มไปหมด\"\r\n\r\n\"ทัตน์ล่ะ มีใครรู้เรื่องนี้บ้าง\"\r\n\r\n\"มีแค่มัมกับแด๊ดนั่นแหละ จริง ๆ ก็เผลอพูดไปหลายครั้งกับพวกไอเฟลม แต่ก็บอกมันว่าฝัน\"\r\n\r\n\"แล้วพ่อแม่เขารีแอคยังไง\"\r\n\r\n\"ตกใจหนักอยู่ แต่ก็อย่างที่บอกนั่นแหละ ชีวิตนี้เราโคตรโชคดีเจอแต่คนดี ๆ ไปหมด ต่างกับชีวิตครั้งก่อนสุด ๆ ไปเลย\"\r\n\r\nไม่มีเสียงตอบรับจากพนักพิงมีชีวิต ทำให้ทิทัตน์หันกลับไปมองอีกคนว่ายังนั่งฟังเขาอยู่หรือหลับไปแล้ว แต่ก็พบเพียงสายตาอ่อนโยนที่มองตอบกลับมา\r\n\r\n\"ขอให้ความทรงจำครั้งนั้นมีแต่เรื่องดี ๆ ได้ไหม อันที่ไม่ดีเดี๋ยวช่วยลบมันทิ้งเอง เริ่มต้นใหม่กันเถอะ\" แล้วพูดด้วยหน้าอ้อน ๆ แบบนั้นใครจะคล้อยตามล่ะ\r\n\r\nเวลาครึ่งคืนผ่านไปไวกว่าที่เคยเป็นในความคิดของทิทัตน์ และจรัลเองก็คงคิดไม่ต่างกัน\r\n\r\n\"ขอคำถามสุดท้าย\"\r\n\r\n\"ครับ\"\r\n\r\n\"ตอนนั้น...เจ็บไหม\" \r\n\r\nทิทัตน์หมายถึงครั้งสุดท้ายที่จิ่งนะและทองคำได้อยู่ด้วยกัน\r\n\r\n\"จำไม่ได้เลย จำได้แค่ว่าเป็นห่วง กลัวว่ามึงจะอยู่ได้ไหม กลัวว่าจะมึงจะโทษตัวเอง เสียใจที่ช่วยได้แค่นั้น ตอนลืมตาครั้งแรกที่นี่จำได้ว่าคำแรกที่พูดคือชื่อมึงแหละ\" แรงกอดที่มากขึ้นทำให้ทิทัตน์รับรู้ถึงความรู้สึกของคนที่โอบกอดเขาได้อย่างดี\r\n\r\n\"ขอโทษนะ ขอโทษจริง ๆ\"\r\n\r\n\"ไม่เอาแล้ว ให้ครั้งนี้เป็นครั้งสุดท้ายที่มึงพูดขอโทษเรื่องนี้นะ\" ทิทัตน์พยักหน้ารับ\r\n\r\n\"ให้ต่อไปมีแต่ทิทัตน์กับจรัล โอเคไหม\"\r\n\r\nไม่มีคำพูดใดหลุดออกมาจากริมฝีปากสวย แต่เป็นจูบเบา ๆ ที่แทนคำตอบทุกอย่างจากทิทัตน์ที่ประทับลงบนอวัยวะเดียวกันของจรัล แค่ปากแตะกันไม่ได้รุกล้ำอะไรเกินกว่านั้น\r\n\r\nแต่ก็ยังอุ่นวาบไปทั้งหัวใจ\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n- 𝒾𝓃 𝒶𝓃𝑜𝓉𝒽𝑒𝓇 𝓁𝒾𝒻𝑒 -\r\n\r\n\r\n\r\n\r\n\r\nทิทัตน์ลืมตาขึ้นมาคนเดียวบนเตียงกว้าง ไร้วี่แววเจ้าของห้องที่นอนอยู่ข้างกันเมื่อคืน จรัลคงออกไปทำงานแล้ว เมื่อเช็กเวลาแล้วยังพอมีเวลาเหลือเฟือก่อนไปทำงาน แมวขี้เซาจึงล้มตัวลงนอนอีกครั้ง\r\n\r\nโชคดีที่อาการเจ็ทแล็กไม่ได้เล่นงานเขา เพียงแต่ช่วงที่ผ่านมาทิทัตน์พักผ่อนได้น้อย ใจจริงเขาอยากจะหยุดงานอีกสักวันเสียด้วยซ้ำ แต่พอนึกถึงหน้าเพื่อนที่ต้องทำงานแทนเขาอีกวันก็นึกสงสารขึ้นมา\r\n\r\nรู้สึกตัวตื่นอีกครั้งเพราะรู้สึกถึงแรงกอดจากคนที่ประชุมเสร็จเร็วและรีบกลับมาหา\r\n\r\nเหมือนฝันเลย\r\n\r\nถึงจะไม่ได้ตื่นมาข้างกัน แต่แค่ได้รู้สึกถึงการมีอยู่ของจรัลก็ทำให้ทิทัตน์อยากตื่นขึ้นมามากกว่าเดิมในทุก ๆ เช้า\r\n\r\n\"ตื่นเร็วครับ เจแวะซื้อข้าวมาให้แล้ว\"\r\n\r\n\"ประชุมเสร็จเร็วเหรอ\"\r\n\r\n\"แอบออกมาน่ะ\"\r\n\r\n\"ไม่ได้สิ จะมาเสียการเสียงานแบบนี้ได้ยังไง!\" ในหัวจรัลตอนนี้คิดแค่ว่าขนาดโวยวายน่ารักเหมือนเดิม\r\n\r\n\"หยอกเล่นครับ งานเสร็จเร็วเลยรีบกลับมา\"\r\n\r\n\"แล้วกินข้าวหรือยัง\"\r\n\r\n\"รอกินพร้อมทัตน์\"\r\n\r\n\"งั้นรอแป๊บหนึ่งนะ\" ไม่ลืมที่จะหอมแก้มก่อนวิ่งเข้าห้องน้ำไป\r\n\r\nจรัลมองตามอีกคนด้วยใบหน้าเปื้อนยิ้ม ก่อนลุกขึ้นมาจัดที่นอนให้เข้าที่เข้าทาง และจัดโต๊ะอาหารรอคนที่กำลังเตรียมตัวไปทำงานในช่วงบ่ายคล้อย\r\n\r\nโต๊ะอาหารที่ปกติมีแต่เสียงช้อนส้อมกระทบจานวันนี้กลับปกคลุมไปด้วยรอยยิ้มและบทสนทนาชวนหัวเราะจากผู้อยู่อาศัยสองคนทำให้ห้องดูมีชีวิตชีวาขึ้นมาก\r\n\r\nจรัลเล่าให้ฟังถึงงานที่ออกไปสะสางมาเมื่อช่วงเช้า ทิทัตน์บ่นให้ฟังว่าเขาขี้เกียจแค่ไหนในการลากตัวเองไปทำงานในวันนี้ ไม่วายโดนคนตรงข้ามเอ่ยแซวว่าถ้าไม่พยายามหลบหน้าเขาก็คงมีงานเรียงแถวรอน้อยกว่านี้ จึงได้ฝ่ามือเล็กกว่าประทับลงบนแขนไปหนึ่งครั้ง\r\n\r\n\r\n\r\n\r\n\r\nรถยนต์คุ้นตาพร้อมตุ๊กตาหน้ารถที่ทุกคนคุ้นเคยเคลื่อนเข้ามาหน้าสตูดิโออดามาส เพราะทิทัตน์เข้ามาทำงานในช่วงบ่ายจึงจำเป็นต้องกลับช้ากว่าคนอื่นอย่างช่วยไม่ได้ จรัลจึงออกตัวว่าหลังเจ้าตัวปิดร้านดอกไม้แล้วเสร็จจะมารับ\r\n\r\n\"เอาเหอะ พอคืนดีกับเขาแล้วยิ้มแย้มเชียวนะ \" เป็นเสียงของเฟลมที่เอ่ยทัก\r\n\r\n\"ก็คนมันมีความสุข ให้เดินร้องไห้มาหรือไง\" ทิทัตน์ตอบกลับไปยิ้ม ๆ\r\n\r\nเฟลมส่ายหัวให้กับความปากร้ายของเพื่อนที่มีแค่พวกเขานี่แหละที่ได้รับคำพูดพวกนี้ ทีกับคุณจรัลน่ะพูดเพราะเชียว ยิ่งกับพวกผู้ใหญ่แล้วทิทัตน์คือเด็กที่ครูทุกคนอยากส่งประกวดเด็กมารยาทดีไม่เกินจริงหรอก\r\n\r\nไม่รู้ว่าเป็นบุญหรือเวรกรรมที่พวกเขาได้เห็นด้านนี้ของมัน แต่อีกความคิดเขาก็ดีใจที่เห็นเพื่อนดูสดใสกว่าเก่ามากขนาดนี้ เป็นภาพที่ไม่คุ้นตาแต่ก็เป็นสิ่งที่เฟลมหวังมาตลอดให้เกิดขึ้นกับเพื่อนรักของเขา\r\n\r\n\"ปากดีนักก็ไปเคลียร์งานนู่นไป\"\r\n\r\n\"ครับพี่\"\r\n\r\n\r\n\r\nดอกไม้ช่อสวยบนโต๊ะทำงานเรียกรอยยิ้มจากเจ้าของห้องเสื้ออีกครั้ง มือสวยหยิบเอากระดาษใบเล็กที่วางอยู่ข้างกันขึ้นมาอ่าน จรัลก็คือจรัล สม่ำเสมออย่างไรก็เป็นอย่างนั้น คงแวะเอาดอกไม้มาให้ตั้งแต่ช่วงเช้าแล้วจึงเข้าบริษัท \r\n\r\nชีวิตประจำของทิทัตน์เป็นไปตามครรลองเดิม มีเพียงความเสียใจกับเรื่องราวในความทรงจำที่เคยเป็นดั่งเมฆหมอกบาง ๆ ที่ปกคลุมหัวใจที่ถูกสายฝนอ่อนโยนของจรัลช่วยลบล้างให้เท่านั้นที่หายไป เผยโฉมทิทัตน์ที่สดใสกว่าวันวานในตอนนี้\r\n\r\nเมื่อถึงเวลาเลิกงานรถยนต์คันเดียวกับที่มาส่งเมื่อเช้าก็เข้ามาจอดเทียบที่ด้านหน้า ส่วนเจ้าของรถออกมายืนรอเปิดประตูให้เหมือนอย่างเคย \r\n\r\n\"เหนื่อยหรือเปล่า กลับไปอาบน้ำก่อนไหม\"\r\n\r\n\"ไม่เลย รีบไปกันเถอะ ปล่อยให้ผู้ใหญ่รอไม่น่ารักนะ\"\r\n\r\nทิทัตน์ที่เกือบลืมไปแล้วว่าตกปากรับคำกับพ่อและป๊าของจรัลไปเมื่อวานว่าจะไปทานอาหารด้วยวันนี้ ขณะที่มือสวยจะกดโทรหาจรัลเพื่อบอกว่าไม่ต้องรีบมารับเขา กลายเป็นเห็นข้อความเตือนจากจรัลแทนว่ามีนัดหลังเลิกงาน ทิทัตน์จึงเร่งเคลียร์งานของวันนี้ให้เสร็จทันจนได้\r\n\r\nแต่ทิทัตน์ลืมคิดไปว่าการจราจรในเมืองหลวงประเทศนี้เป็นอย่างไร ทำให้ตอนนี้ทั้งสองคนติดอยู่กลางถนนมาสักพักแล้ว\r\n\r\n\"นี่ ทำไมวันนั้นถึงเดินเข้าไปในสวน\" ทิทัตน์หมายถึงตอนที่เราสองคนเจอกันโดยบังเอิญในสวนที่แม่ฮ่องสอน เพราะเมื่อคืนพวกเขาเปิดใจเรื่องในอดีตไปหมดแล้ว ตอนนี้คือชั่วโมงของคำถามหลังได้รู้จักกันแล้ว\r\n\r\n\"สารภาพว่าแบตหมดจริง ๆ แล้วก็คงคิดถึงมั้งเลยเดินเข้าไป ตอนหนีออกจากบ้านไปก็ไปเจอที่นี่แหละ ใครจะคิดว่าได้เจอคนในความคิดนอนร้องไห้ใต้ต้นทุเรียนล่ะ\"\r\n\r\n\"หึ นั้นสินะ\"\r\n\r\n\"ทัตน์\"\r\n\r\n\"ว่ายังไง\"\r\n\r\n\"ขอบคุณที่กลับมาอยู่ข้างกันนะ\"\r\n\r\n\"ขอบคุณที่รักกูขนาดนี้เหมือนกันนะ\"\r\n\r\n\r\n\r\n\r\n\r\n- 𝒾𝓃 𝒶𝓃𝑜𝓉𝒽𝑒𝓇 𝓁𝒾𝒻𝑒 -\r\n\r\n\r\n\r\n', 1, '2025-07-09 00:42:07', 0, 'draft', NULL),
(2, 1, 'Lost boy', '- 𝒾𝓃 𝒶𝓃𝑜𝓉𝒽𝑒𝓇 𝓁𝒾𝒻𝑒 -\r\n\r\nจรัสณรงค์กุล เป็นตระกูลนักธุรกิจที่ครอบคลุมในหลายด้านที่มีผู้นำในปัจจุบันคือ จรินท์และจิรันดร์ จรัสณรงค์กุล มีบุตบุญธรรมที่เป็นทายาทสายตรงเพียงสองคนคือ จิรัช จรัสณรงค์กุล พี่ชายคนโต นักแสดงหนุ่มชื่อดังมากความสามารถและว่าที่ผู้บริหารในอนาคต ส่วนน้องชายคนเล็กของบ้านอย่าง จรัลรมย์ จรัสณรงค์กุล ก็เริ่มเข้ามาสานต่องานตั้งแต่เรียนจบแทนพี่ชายที่กำลังสนุกกับชีวิตท่ามกลางสปอร์ตไลท์ แม้ส่วนใหญ่จะดูแลธุรกิจเกี่ยวกับดอกไม้ให้กับจิรันดร์แต่ลูกคนเล็กของบ้านก็ยังคงทำหน้าที่ในส่วนอื่นได้อย่างดีเสมอ\r\n\r\nจรัลรมย์ จรัล หรือเจ เป็นดวงใจของบ้าน จิ่งนะรับรู้มันได้จากความทรงจำตั้งแต่ที่ลืมตาในร่างกายที่เหมือนเขาทุกประการเว้นแต่ฐานะความเป็นอยู่ดีกว่ามากโข เขาลืมตาขึ้นมาท่ามกลางอุบัติเหตุบนท้องถนน ความเจ็บปวดจากร่างกายให้ความรู้สึกเด่นชัดกว่าสิ่งใด รถฉุกเฉินนำส่งผู้ป่วยถึงมือแพทย์ผู้เชี่ยวชาญใช้เวลาไม่นานนัก ใบหน้าแรกที่จิ่งนะในร่างของจรัลฝืนมองอย่างลำบากคือจิรัชที่ดวงตาแดงก่ำกำลังวิ่งตีคู่กับเตียงพยาบาลที่กำลังเข็นผู้ป่วยเข้าสู่ห้องผ่าตัดและหยุดลงที่ประตูบานใหญ่ที่คนเป็นพี่ชายไม่มีสิทธิก้าวเข้ามา\r\n\r\nการผ่าตัดผ่านไปได้ด้วยดี เพราะจรัลถูกปฐมพยาบาลอย่างทันท่วงทีเลยทำให้ร่างกายไม่ได้เสียหายมากจนเกินเยียวยา จรัลปกติดีทางร่างกายจากการดูแลโดยทีมแพทย์ฝีมือดีของโรงพยาบาลเป็นเวลาหลายเดือน แต่สิ่งที่แปลกไปคือจรัลเงียบขรึมและไม่ปริปากพูดอะไรกับครอบครัวเลยแม้แต่น้อย ต่างจากก่อนหน้านี้ที่เคยเป็นเหมือนแสงสว่างของบ้าน แพทย์ประจำตัวลงความเห็นว่าเป็นสิ่งที่เกิดขึ้นได้กับผู้ป่วยที่ผ่านการเหตุการณ์ร้ายแรงจนมีผลกระทบในจิตใจ\r\n\r\nแต่จิรันดร์ที่เฝ้ามองลูกชายคนเล็กอยู่ตลอดรู้อยู่ในใจว่ามีอะไรที่เปลี่ยนไป แต่ผู้เป็นพ่อยังไม่รู้ว่าสิ่งที่ว่านั้นคืออะไร เด็กสดใสแต่ไม่ค่อยมีเพื่อน ชอบอยู่คนเดียวแต่ไม่ถึงกับเก็บตัวเช่นนี้ แววตาที่มองครอบครัวก็ต่างออกไปคล้ายกับว่ารู้สึกผิดอยู่ตลอดเวลา แต่พวกเขาไม่รู้ว่าเด็กตรงหน้ารู้สึกผิดในเรื่องใด จรัลประสบอุบัติเหตุขณะขับขี่รถจักรยานยนต์ของขวัญอายุครบสิบแปดที่จรินท์ ป๊าของเจ้าตัวเป็นคนซื้อให้ และถูกรถยนต์ที่บรรทุกเหล็กก่อสร้างเสียหลักพุ่งชนขณะจอดรอสัญญาณไฟห่างจากหน้าโรงเรียนเพียงไม่ไกลในวันสุดท้ายของภาคเรียน เจ้าหน้าที่กู้ภัยที่จิรัชเจอตอนนำตัวน้องชายของเขามารักษาบอกว่าจรัลโชคดีที่เหล็กจากรถคู่กรณีไม่เสียงเข้าที่คอของเจ้าตัวแต่หล่นลงมาห่างจากคอของจรัลเพียงไม่ถึงสิบเซนติเมตรเท่านั้น แม้ทั้งร่างจะเสียหายแทบทุกส่วนแต่เวลาและการรักษาที่ดีก็ยังคงเยียวยาจนหายได้\r\n\r\nเป็นเวลาเกือบปีที่บ้านจรัสณรงค์กุลไม่ได้ยินเสียงลูกชายคนเล็ก พวกเขาปรับตัวได้แล้วกับการทำใจยอมรับว่าจรัลคงเปลี่ยนไปแล้วจริง ๆ แต่จุดพลิกผันที่ทำให้คนเป็นพ่อและป๊าต้องจำใจและขอร้องให้จรัลบอกสิ่งที่อยู่ในใจก็คือเหตุการณ์ที่เจ้าตัวหนีออกจากบ้าน หลังจากกลับมารักษาตัวที่บ้านได้เพียงสองเดือนหลังจากแพทย์ประเมินทั้งร่างกายและจิตใจว่าปกติดีแล้วเพียงแต่เจ้าตัวไม่ยังไม่ยอมพูดก็เท่านั้น จรัลหายตัวออกจากบ้านไปในเช้ามืดวันหนึ่ง จนสุดท้ายได้เบาะแสจากตำรวจท้องที่จังหวัดแม่ฮ่องสอนสามวันต่อมาว่าพบเจ้าตัวอยู่ในจังหวัดนี้และยังคงไม่มีคำใดหลุดออกมาจากปากชายหนุ่มอีกเช่นเคย \r\n\r\nตลอดการเดินทางกลับจากแม่ฮ่องสอนมีเพียงความเงียบที่โรยตัวโอบล้อมจรัสณรงค์กุล จรินท์ทำเพียงนั่งมองหน้าลูกชายคนเล็กอยู่อย่างนั้นโดยไม่เอ่ยคำใดอยู่ที่ห้องนั่งเล่นกลางบ้าน แววตารู้สึกผิดฉายชัดกว่าครั้งใด จรัลทำหน้าจะร้องไห้เป็นครั้งแรกหลังจากเกิดอุบัติเหตุครั้งนั้น จิรันดร์โดนลูกชายคนโตคว้าแขนไว้ตอนที่กำลังจะเข้าไปทำลายสงครามประสาทของป๊าและลูกชายคนเล็ก\r\n\r\n\"เจคุยกับป๊าได้ไหม เจมีอะไรในใจเจบอกป๊าได้ไหมลูก\" จรัลตาเบิกกว้างด้วยความตกใจ เพราะจรินท์ลุกออกจากโซฟาฝั่งตรงข้ามแล้วมาคุกเข่าลงตรงหน้าลูกชาย\r\n\r\n\"ป๊ารู้ว่าเจกำลังต่อสู้กับอะไรสักอย่างข้างในนั้น ป๊ารอมาตลอด รอให้เจบอกรอให้เจพร้อมที่จะเล่าให้ฟัง ป๊าขอนะครับ เจคุยกับพวกเราได้ไหมลูก ป๊าจะไม่ตัดสินเจเลย แค่เจบอกป๊าได้ไหมว่าเจรู้สึกอะไรอยู่ ป๊าอยากเข้าใจ ป๊า พ่อ กับพี่จิอยากยืนข้าง ๆ และสู้เพื่อเจนะ\" \r\n\r\nจรัลมองดวงตาแดงก่ำที่น่าจะเกิดจากการอดนอนเพื่อตามหาเขาและอดกลั้นน้ำตาไม่ให้ไหลออกมา เวลาผ่านไปสักพักมีเพียงเสียงสะอื้นจากจิรันดร์ที่อยู่ในอ้อมกอดของลูกชายคนโตดังออกมาเป็นพัก ๆ\r\n\r\n\"ผมไม่ใช่จรัล...ครับ\" ไม่รู้ว่าเสียงแรกจากลูกชายคนเล็กในรอบปีหรือเนื้อหาในคำพูดกันแน่ที่เป็นสาเหตุให้ทุกคนในบ้านจ้องเขาอย่างตกใจบวกกับไม่เข้าใจเช่นนี้\r\n\r\n\"โอเค งั้น เราเป็นใครบอกป๊าได้ไหม\" เป็นจรินท์ที่หาเสียงของตัวเองเจอก่อนและเอ่ยถาม\r\n\r\n\"ผมชื่อจิ่งนะครับ\"\r\n\r\nหลังจากนั้นเรื่องราวมากมายก็ถูกถ่ายทอดออกมาจากปากของคนที่บอกว่าไม่ใช่จรัล จิ่งนะสารภาพว่าที่ไม่พูดออกไปสักทีเพราะกลัวทั้งสามคนเสียใจที่คนที่ตื่นมาในร่างกายนี้เป็นเขาแทนที่จะเป็นลูกและน้องชายของครอบครัวนี้ ยิ่งยืดเวลานานไปเท่าไหร่ก็ยิ่งไม่กล้าพูดออกไปมากกว่าเดิม เขารู้สึกผิดเสมอที่ทุกคนเอาใจใส่และดูแลเขาอย่างดี เป็นที่มาของแววตารู้สึกผิดที่แสดงออกมาทุกวัน และที่ออกจากบ้านไปเพราะต้องการกลับไปที่ที่เขาเคยใช้ชีวิตเผื่อจะใช้ยืนยันคำพูดตัวเองได้ แต่ก็ไม่มีอะไรเป็นดังความคิด ที่ดินตรงนั้นโล่งกว้าง มีทุกสิ่งแต่ก็ขาดทุกอย่างอยู่ดี\r\n\r\nเมื่อเห็นทุกคนไม่พูดอะไร จิ่งนะจึงเล่าเรื่องต่อไปเรื่อย ๆ ไม่ลืมที่จะบอกว่าเขายังมีทุกความทรงจำของจรัลคนนั้นอยู่ครบถ้วน เมื่อก่อนเขาคือใคร ชื่ออะไร เกิดอะไรขึ้นบ้างกับชีวิตเส็งเคร็งที่พอจะได้มีความสุขก็ถูกพรากไปอย่างง่ายดาย พอได้พูดก็คล้ายกับว่าเขาจะหยุดพูดไม่ได้ เมื่อเรื่องสุดท้ายของชายที่ชื่อว่าจิ่งนะ จองย้อยจบลง อ้อมกอดจากจิรันดร์ทำให้ไหล่ของชายหนุ่มที่ก้มหน้าเล่าเรื่องของตัวเองด้วยความรู้สึกผิดสั่นเทาขึ้นมาเช่นกัน น้ำตาที่ไหลและเสียงตะกุกตะกักพูดขอโทษไม่ขาดปาก เขาไม่อยากมาแทนที่ใครและไม่อยากทำให้ใครลำบากอีกแล้ว\r\n\r\n\"จิ่งนะ ฟังป๊านะ ต่อจากนี้เราคือจรัล จรัลรมย์ จรัสณรงค์กุล ลูกชายของป๊ากับพ่อ น้องชายของพี่จิ อย่ารู้สึกผิดที่ได้ชีวิตนี้มา เพราะทุกคนในบ้านยินดีกับการมีอยู่ของเจนะ\" จรินท์พูดออกมาเป็นคนแรก\r\n\r\nในช่วงที่จรัลยังอยู่ในโรงพยาบาล ท่าทีที่เปลี่ยนไปแต่ไม่ได้มีสาเหตุจากการเจ็บปวดทำให้เขาและสามีตัดสินใจได้ลองปรึกษาที่ปรึกษาทางจิตวิญญาณอยู่บ้าง เพื่อให้มีที่ยึดเหนี่ยวจิตใจ พอ ๆ กับคำตอบที่บอกว่าลูกชายคนโตจะโด่งดังในหน้าที่การงานทุกครั้งก็มักจะได้คำพูดที่ว่า \'คนที่จากไป ได้ไปในที่ที่ควรแล้ว ส่วนคนที่ยังอยู่เพราะเขายังต้องอยู่เพื่อบางสิ่ง เพื่อรัก เพื่อถูกรัก...\'  \r\n\r\nเพราะอย่างนั้นการที่ความจริงออกมาในรูปแบบนี้เขาและสามีเตรียมใจไว้นานมากแล้ว จิรัชเองก็เช่นกัน แม้จะตกใจอยู่บ้างกับเรื่องที่เพิ่งได้รับฟังแต่ผลตรวจสุขภาพเมื่อสองเดือนที่แล้วก็เป็นครื่องยืนยันแล้วว่าน้องชายเขาปกติดีทุกอย่าง ภาพที่ทั้งครอบครัวกอดกันกลมร้องไห้ในห้องนั่งเล่นเป็นสิ่งที่เกิดขึ้นครั้งแรกและคงเป็นครั้งสุดท้ายของบ้านหลังใหญ่ที่อบอุ่นหลังนี้ \r\n\r\nหลังปรับความเข้าใจและปรับตัวเข้ากับครอบครัวใหม่อยู่พักใหญ่ จรัลจึงได้กลับมาเรียนมหาวิทยาลัยอย่างที่จรัลคนเดิมตั้งใจไว้ เด็กคนนั้นรักครอบครัวมาก อยากสานต่อกิจการของครอบครัวเพื่อที่ป๊ากับพ่อจะได้เกษียณตัวเองไปใช้ชีวิตเรียบง่ายแบบที่อยากใช้ รู้ว่าพี่ชายรักการแสดงมากขนาดไหนจึงจะช่วยทำงานทุกอย่างไว้ให้ก่อนโดยไม่เกี่ยงงอนเลยสักครั้ง และเขาตั้งใจจะทำให้ทุกสิ่งที่คนคนนั้นตั้งใจไว้เป็นจริง เพราะจรัลเป็นคนขยันความรู้ที่อีกคนมีทำให้เขาสานต่อสิ่งที่เด็กคนนั้นทำไว้ได้อย่างดี ทุกอย่างดีขึ้นเรื่อย ๆ ในปีต่อ ๆ มา เขาเข้ากับทุกคนได้อย่างดี โดยเฉพาะกับจิรัชที่ยอมรับในตัวตนเขาและสนิทกับจรัลคนนี้อย่างสนิทใจไม่ต่างจากตอนเด็ก ๆ จนแซวเขาด้วยซ้ำว่าถ้าตอนแรกเขาสวมรอยเป็นจรัลคนก่อนก็คงไม่มีใครจับได้ แต่เพราะเขาจริงใจและไม่เห็นแก่ตัว เรื่องเลยออกมาเป็นอย่างนี้\r\n\r\nจรัลน่ะ ทั้งเป็นเด็กดี แล้วก็สมควรถูกรักที่สุด\r\n\r\nชีวิตของจรัลวนอยู่กับการเรียนและการทำงานวนอยู่อย่างนั้น จนป๊ากับพ่อเอ่ยปากถึงเรื่องแฟนแม้จะรู้อยู่แล้วว่าเรื่องราวเขาเป็นมายังไงแต่ก็คอยสนับสนุนให้ลองดูใหม่เสมอ จรัลจึงเอ่ยกลับไปว่าจะลองเปิดใจหลังจากเรียนจบปริญญาโท\r\n\r\nและดูเหมือนคำพูดของเขาจะเป็นจริงขึ้นมาทันตาเห็น ปีที่สองในมหาวิทยาลัยชั้นนำในประเทศอังกฤษที่เขากำลังเป็นนักศึกษาทำให้เขาได้บังเอิญเจอกับใครบางคน คนที่คุ้นหน้าและรู้สึกคุ้นเคยทางความรู้สึก คนที่วิ่งหน้าตั้งหาห้องเรียนตัวเองให้ทัน จรัลยืนมองจนอีกคนลับสายตาจึงได้เดินต่อไป ก็คงเป็นไปได้กับการที่จะมีคนหน้าซ้ำที่คุ้นเคยบนโลกใบนี้จนส่งผลต่อความรู้สึกภายในใจ\r\n\r\nเขาเจอทิทัตน์อีกครั้งที่ปาร์ตี้ในแฟลตของนักเรียนไทยสักคนที่ชวนเขามา และดูท่าจะชวนคนไทยแถบนั้นทุกคน เขารู้ชื่อคนคุ้นหน้าจากเพื่อนชาวต่างชาติที่ลงวิชาเสริมเกี่ยวกับแฟชั่นเพราะเห็นเพื่อนพูดคุยกับคนคนนั้นพอดี พอสบโอกาสเลยดึงเพื่อนมาถามไถ่กันสักหน่อย แต่จรัลก็ทำเพียงเท่านั้น แค่มองอยู่ไกล ๆ ไม่เข้าไปให้เห็นหน้า\r\n\r\nทิทัตน์ ธีโอดอร์ แคสลีย์ เป็นชื่อที่เหมาะสมกับคนคนนี้แล้ว\r\n\r\nตลอดระยะเวลาการเรียนที่เดียวกันไม่ได้ทำให้จรัลกล้าคุยกับอีกคน ยกเว้นตอนที่ทิทัตน์เมาหัวราน้ำที่บาร์ประจำแถวโซโห เป็นร้านที่ตกแต่งให้กลิ่นอายคล้ายโบสถ์ ไม่รู้ว่าเจ้าของคิดอะไรอยู่ตอนออกแบบร้านจรัลก็ไม่แน่ใจ แต่อย่างหนึ่งที่สะดุดตาในร้านคือตู้สารภาพบาปที่หน้าตาละม้ายคล้ายของจริงที่อยู่ในโบสถ์เกือบหนึ่งร้อยเปอร์เซ็นต์ที่ไม่รู้ว่าเจ้าของร้านไปหามาจากไหนอีกนั่นแหละ และตู้สารภาพบาปนั่นเองที่ทิทัตน์ชอบเข้าไปนั่ง ไม่ทราบว่าเจ้าตัวรู้หรือเปล่าว่าเวลาเมาน่ะ ชอบเล่าเรื่องให้คนอื่นฟังขนาดไหน แถมยังพูดเป็นภาษาไทยด้วยซ้ำ คงไม่คิดว่าจะมีคนอื่นฟังภาษาไทยได้เหมือนกัน หรือคิดว่าถึงใครจะได้ฟังก็คงไม่คิดใส่ใจอะไรล่ะมั้ง หลังจากคอยมองหาอีกคนมาร่วมเดือน จรัลตัดสินใจเดินตามทิทัตน์เข้าไปในตู้สารภาพบาปอีกด้านและได้ฟังในสิ่งที่เขาก็ไม่คาดคิดว่าจะเกิดขึ้นจริง\r\n\r\nให้ตาย แค่เขาได้มีชีวิตใหม่ก็น่าทึ่งมากพอแล้ว แต่ทิทัตน์ที่กำลังพูดเรื่องที่คล้ายว่าก็เกิดขึ้นกับเขาเช่นกันอยู่ตอนนี้ ทำเอาจรัลพูดอะไรไม่ออก\r\n\r\n\"คุณรู้เปล่า ผมอะ อยู่ดี ๆ ก็ได้ชีวิตนี้มาใช้ หน้าตาเหมือนเดิมเลยเว้ย ผมได้ทำตามฝันทุกอย่างเลย แต่ผมคิดถึงไอจิ่งนะ\" ชื่อที่ไม่ได้ยินมานานและคงไม่มีใครเรียกอีกแล้วหลุดออกมาจากปากคนเมา\r\n\r\n\"ผมไม่กล้าใช้ชีวิตเหลวแหลกเลย กลัวมันจะมองจากที่ไหนมาแล้วเสียใจ\" ไม่เลย ไม่เคยเสียใจสักครั้ง\r\n\r\nเสียงคนเมาเงียบไปสักพัก ไม่นานเสียงเรียกชื่อทิทัตน์ก็ดังใกล้เข้ามา ตามด้วยเสียงเปิดประตูฝั่งตรงข้าม ทิทัตน์ออกไปแล้ว\r\n\r\nหลังจากรับรู้สิ่งนี้อย่างไม่ตั้งใจ จากที่เคยเรียนและทำงานวนอยู่แบบนั้นจรัลก็มีกิจวัตรประจำวันเพิ่มเข้ามาคือการแบ่งเวลามานั่งรอเผื่อวันไหนทิทัตน์จะแวะเข้ามาที่บาร์บ้าง เหมือนสุนัขรอเจ้าของอย่างไรอย่างนั้น และวันไหนโชคดีทิทัตน์กับกลุ่มเพื่อนก็แวะมาสังสรรค์กันและจบที่คนคุ้นหน้าของเขาจะเข้าไปตู้สารภาพบาปปลอม ๆ นั่น และมีเพียงจรัลที่นั่งอยู่อีกฝั่งรับฟังทุกคำพูดอย่างตั้งใจ\r\n\r\n\"คิดถึงชีวิตใช้แรงงานอยู่เหมือนกันนะ คิดถึงเฉย ๆ น่ะ คิดถึงเวลาได้ทำสวนกับจิ่งนะ\" ขอให้ได้อยู่ทำสวนกับมึงไปนาน ๆ ได้แต่ขอโทษอีกฝ่ายในใจ\r\n\r\n\"จะเรียนจบแล้ว งานก็เยอะจนแทบไม่มีเวลาเลย ทำไปทำมาก็เหนื่อย พอ ๆ กับที่ทำสวนเลยนี่หว่า แต่แบบนี้ก็ดีจะได้คิดถึงจิ่งนะน้อยลง\"\r\n\r\n\"ทำไมได้กันแล้วไม่จบ ๆ กันไปนะ จะมาชอบอะไรคนแบบกูวะ คนแบบนี้จะไปรักษาใครไว้ได้\"\r\n\r\n\"ทำได้แล้วอะ เปิดห้องเสื้อของตัวเองได้แล้วว่ะ ถ้ามึงรู้มึงจะดีใจไหมวะจิ่งนะ\" ดีใจสิ ดีใจที่สุดเลย\r\n\r\n\"อีกสักปีคงย้ายไปอยู่ที่ไทย ที่นี่มันดีมาก ๆ แต่คิดถึงบรรยากาศที่ได้อยู่ในสวนตลอดเลย พูดอะไรล่ะเนี่ย กลับไปก็คงอยู่แต่กรุงเทพอยู่ดี แต่ก็ถือว่าใกล้มึงอีกนิดละกันเนอะ\"\r\n\r\n\"คิดถึงนะจิ่งนะ ผีไม่มีจริงแน่ ๆ มึงไม่เคยมาหากูเลย หรือตามมาโลกนี้ไม่ได้วะ แย่มากเลยว่ะ\"\r\n\r\n\"กูคงรักใครไม่ได้แล้วมั้ง รักมึงอยู่คนเดียวเลยตลอดมา กี่ปีแล้วเนี่ย ก็รักแต่มึง\"\r\n\r\n\"บางทีก็อยากจะเจอคนที่รักกู แล้วไม่ทำให้นึกถึงเรื่องที่ผ่านมาบ้างว่ะ คนที่ทำให้เลิกนึกถึงมึง เฮ้อ ทำให้คิดถึงมึงได้อยู่แต่ขอให้เต็มไปด้วยความทรงจำดี ๆ เติบโตมาด้วยความรักที่ถูกต้องอ่า\"\r\n\r\n\"อยากรักษามึงไว้ในชีวิตให้ได้จริง ๆ นะ จิ่งนะ...\"\r\n\r\nจรัลรับรู้ความรู้สึกมากมายของทิทัตน์จากการเข้าไปนั่งข้าง ๆ เช่นนี้ตลอดจนจบปีการศึกษาและเป็นเขาที่ต้องกลับไปทำงานต่อ จากที่เคยคิดจะแสดงตัวว่าเป็นใคร จรัลก็เปลี่ยนใจยืดเวลาไปอีกเรื่อย ๆ และโชคชะตาก็พาอีกคนมาพบกับเขาอีกครั้ง\r\n\r\nจรัลจำแววตาที่ทิทัตน์มองเขาครั้งแรกได้ ทั้งความตกใจและความผิดหวังก่อขึ้นในดวงตาสวยคู่นั้นจนเก็บไว้ไม่หมด คงตกใจที่ได้เห็นใบหน้าที่คุ้นเคย แต่ก็ผิดหวังเมื่อคิดว่าไม่ใช่คนที่ตัวเองรัก จรัลเข้าหาเจ้าของห้องเสื้อคนเก่งด้วยจุดประสงค์ที่ชัดเจน แต่เขาอยากให้อีกคนได้ลองเปิดใจกับการรักใครใหม่สักคนดูก่อน เขาอยากให้ทิทัตน์ละทิ้งความจำที่เลวร้ายในอดีต และเริ่มต้นใหม่ได้เต็มร้อย\r\n\r\nแต่จรัลคิดผิด แผลในใจของทิทัตน์ยังเด่นชัดเสมอ และคงแก้ไขด้วยตัวของทิทัตน์เองไม่ไหว จรัลเข้าใจแล้วว่าเขาควรคุยกับอีกคนอย่างตรงไปตรงมา แผลในใจทิทัตน์มาจากเขา หากปล่อยให้หายเองเกรงว่าชั่วชีวิตของเจ้าตัวก็คงไม่เพียงพอ เพราะอย่างนั้นเขาก็ควรจะเป็นคนช่วยรักษามันไปพร้อมกับทิทัตน์\r\n\r\n\r\n\r\n- 𝒾𝓃 𝒶𝓃𝑜𝓉𝒽𝑒𝓇 𝓁𝒾𝒻𝑒 -\r\n\r\n  \r\n\r\nข้อความล่าสุดจากจรัลไม่ได้ถูกตอบกลับมาจากคนที่อยู่คนละเขตเวลา อาจจะเพราะทิทัตน์ปิดมันไว้ขณะอยู่บนเครื่องบิน ชายหนุ่มจึงขับรถไปที่ห้องเสื้อของทิทัตน์ในวันถัดมา เมื่อรู้ว่าเซเนีย ผู้ช่วยที่งานค่อนข้างจะรัดตัวเป็นคนไปรับผู้เป็นเจ้านายจากสนามบินในตอนบ่ายคล้อยของวัน เขาจึงอาสาทำแทนโดยขอใช้รถของคุณผู้ช่วยเองในการขับไปสนามบิน จรัลให้เหตุผลว่าเพราะทิทัตน์คงมองหารถของผู้ช่วยได้ไวกว่ามองหารถของเขา อาจจะถือเป็นการมัดมือชกไปเสียหน่อยที่เขาทำแบบนี้ แต่ทิทัตน์น่ะ ต้องให้คุยต่อหน้าถึงจะเลิกดื้อและยอมฟังกันดี ๆ\r\n\r\nจรัลก็ได้แต่หวังว่าอีกคนจะยอมคุยกับเขาดี ๆ ก็เท่านั้น\r\n\r\n', 2, '2025-07-09 00:43:46', 0, 'draft', NULL),
