--
-- Triggers `chapters`
--
DELIMITER $$
CREATE TRIGGER `trg_chapters_ai` AFTER INSERT ON `chapters` FOR EACH ROW BEGIN
  -- ส่งแจ้งเตือนเฉพาะตอนที่ "เผยแพร่แล้ว"
  IF NEW.status = 'published' THEN
    INSERT INTO notifications (
      users_id, actor_user_id, type, reference_id,
      novel_id, chapter_id, message, is_read, created_at
    )
    SELECT 
      b.users_id, 
      n.users_id, 
      'new_chapter', 
      NEW.chapters_id, 
      NEW.novels_id, 
      NEW.chapters_id,
      CONCAT('นิยายที่คุณติดตามมีตอนใหม่: ', n.title, ' ตอนที่ ', NEW.chapter_no),
      0, 
      NOW()
    FROM bookshelf b
    JOIN novels n ON n.novels_id = NEW.novels_id
    WHERE b.novels_id = NEW.novels_id;
  END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_chapters_au` AFTER UPDATE ON `chapters` FOR EACH ROW BEGIN
  -- กรณีเปลี่ยนสถานะจากไม่เผยแพร่/draft มาเป็นเผยแพร่ครั้งแรก
  IF NEW.status = 'published' AND OLD.status <> 'published' THEN
    INSERT INTO notifications (
      users_id, actor_user_id, type, reference_id,
      novel_id, chapter_id, message, is_read, created_at
    )
    SELECT 
      b.users_id, 
      n.users_id, 
      'new_chapter',           -- เหมือนเพิ่งมีตอนใหม่
      NEW.chapters_id, 
      NEW.novels_id, 
      NEW.chapters_id,
      CONCAT('นิยายที่คุณติดตามมีตอนใหม่: ', n.title, ' ตอนที่ ', NEW.chapter_no),
      0, 
      NOW()
    FROM bookshelf b
    JOIN novels n ON n.novels_id = NEW.novels_id
    WHERE b.novels_id = NEW.novels_id;

  -- กรณีตอนเผยแพร่อยู่แล้ว แล้วมีการแก้ไขชื่อ/เนื้อหา
  ELSEIF NEW.status = 'published'
     AND (NEW.title <> OLD.title OR NEW.content_html <> OLD.content_html) THEN

    INSERT INTO notifications (
      users_id, actor_user_id, type, reference_id,
      novel_id, chapter_id, message, is_read, created_at
    )
    SELECT 
      b.users_id, 
      n.users_id, 
      'chapter_updated',       -- การแก้ไขตอน
      NEW.chapters_id, 
      NEW.novels_id, 
      NEW.chapters_id,
      CONCAT('นิยายที่คุณติดตามมีการแก้ไข: ', n.title, ' ตอนที่ ', NEW.chapter_no),
      0, 
      NOW()
    FROM bookshelf b
    JOIN novels n ON n.novels_id = NEW.novels_id
    WHERE b.novels_id = NEW.novels_id;

  END IF;
END
$$
DELIMITER ;

