-- Triggers `chapter_likes`
--
DELIMITER $$
CREATE TRIGGER `trg_chapter_like_ad` AFTER DELETE ON `chapter_likes` FOR EACH ROW BEGIN
  UPDATE chapters SET like_count = CASE WHEN like_count > 0 THEN like_count - 1 ELSE 0 END
  WHERE chapters_id = OLD.chapters_id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_chapter_like_ai` AFTER INSERT ON `chapter_likes` FOR EACH ROW BEGIN
  UPDATE chapters SET like_count = like_count + 1 WHERE chapters_id = NEW.chapters_id;
END
$$
DELIMITER ;

