DELIMITER $$
CREATE TRIGGER `trg_comments_ai` AFTER INSERT ON `comments` FOR EACH ROW BEGIN
  DECLARE author_id INT;
  SELECT users_id INTO author_id FROM novels WHERE novels_id = NEW.novels_id;
  IF author_id IS NOT NULL THEN
    INSERT INTO notifications (users_id, actor_user_id, type, comment_id, novel_id, reference_id, message, is_read, created_at)
    VALUES (author_id, NEW.users_id, 'comment', NEW.cm_id, NEW.novels_id, NEW.cm_id,
            'มีคอมเมนต์ใหม่ในนิยายของคุณ', 0, NOW());
  END IF;
END
$$
DELIMITER ;
