--
-- Triggers `novels`
--
DELIMITER $$
CREATE TRIGGER `trg_novels_completed_bu` BEFORE UPDATE ON `novels` FOR EACH ROW BEGIN
  IF NEW.status = 'จบแล้ว'
     AND (OLD.status <> 'จบแล้ว' OR OLD.status IS NULL)
     AND NEW.completed_at IS NULL THEN
    SET NEW.completed_at = NOW();
  ELSEIF NEW.status <> 'จบแล้ว' THEN
    SET NEW.completed_at = NULL;
  END IF;
END
$$
DELIMITER ;

