--
-- Triggers `ratings`
--
DELIMITER $$
CREATE TRIGGER `trg_ratings_bi` BEFORE INSERT ON `ratings` FOR EACH ROW BEGIN
  IF NEW.rating < 1 OR NEW.rating > 5 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'rating must be between 1 and 5';
  END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_ratings_bu` BEFORE UPDATE ON `ratings` FOR EACH ROW BEGIN
  IF NEW.rating <> OLD.rating THEN
    IF OLD.update_count >= 1 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'rating can be edited only once';
    ELSE
      SET NEW.update_count = OLD.update_count + 1;
      IF NEW.rating < 1 OR NEW.rating > 5 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'rating must be between 1 and 5';
      END IF;
    END IF;
  END IF;
END
$$
DELIMITER ;

